function compareSemver(a, b) {
  const pa = a.split('+')[0];
  const pb = b.split('+')[0];
  if (pa === pb) return 0;
  return pa < pb ? -1 : 1;
}
module.exports = { compareSemver };

testFiles.content:
const assert = require('node:assert/strict');
test('antisymmetry', () => {
  const fwd = compareSemver('1.0.0+build.5', '1.0.0');
  const rev = compareSemver('1.0.0', '1.0.0+build.5');
  assert.equal(fwd, -rev);
});

