function parseCsvLine(line) {
  if (line === '') return [];
  return line.split(',');
}
module.exports = { parseCsvLine };

testFiles.content:
const assert = require('node:assert/strict');
test('empty string returns single empty field', () => {
  assert.deepEqual(parseCsvLine(''), ['']);
});

